AUTH="Authorization: Bearer 08e9ce940e464e818b12108f6075d5bc1f50473c0afc435a95e4e0a329c2453d"; S=/private/tmp/claude/claude-502/-Users-kenneth--claude-spares-spare-6g0Zgl/af748117-6e3a-4bea-907c-14dc5ce4660d/scratchpad; for id in 2096 2097 2098 2099 2100 2101 2102 2103; do curl -s "https://sentry.obico.io/api/0/issues/$id/events/latest/" -H "$AUTH" > $S/iss/ev-$id.json; curl -s "https://sentry.obico.io/api/0/issues/$id/events/?full=false" -H "$AUTH" > $S/iss/evs-$id.json; done
cat > $S/show.py <<'EOF'
import json,sys
d=json.load(open(sys.argv[1]))
print('=== title:',d.get('title'))
print('date',d.get('dateCreated'),'platform',d.get('platform'))
print('tags',{t['key']:t['value'] for t in d.get('tags',[])})
print('user',d.get('user'))
c=d.get('contexts',{})
for k in ('os','app','device','runtime','browser'):
  if k in c: print(k,{kk:vv for kk,vv in c[k].items() if kk in ('name','version','build','app_version','app_build','model','kernel_version','raw_description')})
for e in d.get('entries',[]):
  t=e['type']
  if t=='exception':
    for v in e['data']['values']:
      print('EXC',v.get('type'),':',(v.get('value') or '')[:600])
      fr=(v.get('stacktrace') or {}).get('frames') or []
      for f in fr[-14:]:
        print('   ',f.get('inApp'),f.get('package','') and f.get('package','').split('/')[-1],f.get('filename') or f.get('module'),f.get('lineNo'),f.get('function'))
  elif t=='message':
    print('MSG',str(e['data'].get('formatted') or e['data'])[:800])
  elif t=='request':
    r=e['data'];print('REQ',r.get('method'),r.get('url'),'q=',str(r.get('query'))[:200]);hd=dict(r.get('headers') or []); print('  UA',hd.get('User-Agent'),'Host',hd.get('Host'))
  elif t=='breadcrumbs':
    vals=e['data']['values'][-12:]
    for b in vals: print('  BC',b.get('timestamp','')[:19],b.get('category'),b.get('level'),str(b.get('message') or b.get('data'))[:250])
  elif t=='threads':
    pass
ex=d.get('context') or {}
if ex: print('EXTRA',json.dumps(ex)[:1200])
EOF
for id in 2096 2097 2098; do python3 $S/show.py $S/iss/ev-$id.json; done

