                device_id = named.device_id;
    if (const auto name = strip(printer_id, kNamedPrefix); name && device_id.empty()) {
        open_printer_window(*name);
        return;
    }
    if (device_id.empty())
        return; // the card changed under the click; the refreshed rail says so
