#include "Files.hpp"

#include <cerrno>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <ios>
#include <stdexcept>
#include <string>

namespace Slic3r::GUI::JusPrin {

void write_file(const std::filesystem::path& path, const std::string& content)
{
    std::filesystem::create_directories(path.parent_path());
    // Appended to the path itself: path.string() on Windows converts to the
    // system's code page, and throws for a name with characters outside it.
    std::filesystem::path temp = path;
    temp += ".tmp";
    {
        std::ofstream out(temp, std::ios::binary | std::ios::trunc);
        if (!out.is_open())
            throw std::runtime_error("could not create " + temp.u8string() + ": " + std::strerror(errno));
        out << content;
        out.close();
        if (!out)
            throw std::runtime_error("could not write " + temp.u8string() + ": " + std::strerror(errno));
    }
    std::filesystem::rename(temp, path);
}

} // namespace Slic3r::GUI::JusPrin
// The file helpers JusPrin's own code writes with.

#include <catch2/catch_all.hpp>
#include <catch2/catch_test_macros.hpp>

#include "slic3r/GUI/JusPrin/Support/Files.hpp"

#include <exception>
#include <filesystem>
#include <fstream>
#include <ios>
#include <iterator>
#include <random>
#include <string>

#ifndef _WIN32
#include <csignal>
#include <sys/resource.h>
#endif

using namespace Slic3r::GUI::JusPrin;
namespace fs = std::filesystem;

namespace {

fs::path fresh_folder()
{
    const fs::path folder = fs::temp_directory_path() / ("jusprin-files-" + std::to_string(std::random_device{}()));
    fs::create_directories(folder);
    return folder;
}

std::string read(const fs::path& path)
{
    std::ifstream in(path, std::ios::binary);
    return {std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>()};
}

} // namespace

TEST_CASE("a written file holds all of its content, in a folder made for it", "[Files]")
{
    const fs::path folder = fresh_folder();
    const fs::path file   = folder / "inner" / "model.stl";
    write_file(file, "solid cube\nendsolid cube\n");
    CHECK(read(file) == "solid cube\nendsolid cube\n");
    fs::remove_all(folder);
}

TEST_CASE("a file named in any language is written, whatever the system's own language", "[Files]")
{
    // On a Windows set to English, these characters have no place in the
    // system's code page.
    const fs::path folder = fresh_folder();
    const fs::path file   = folder / fs::u8path("\xE6\xA8\xA1\xE5\x9E\x8B \xD0\xBA\xD1\x83\xD0\xB1.3mf");
    write_file(file, "PK");
    CHECK(read(file) == "PK");
    fs::remove_all(folder);
}

