// Stand-in Sentry server: keeps every envelope's event message, so no report reaches production.
const http = require('http'); const fs = require('fs'); const zlib = require('zlib');
const out = process.argv[2];
http.createServer((req, res) => {
  const chunks = [];
  req.on('data', c => chunks.push(c));
  req.on('end', () => {
    let buf = Buffer.concat(chunks);
    try { if ((req.headers['content-encoding'] || '').includes('gzip')) buf = zlib.gunzipSync(buf); } catch (e) {}
    const body = buf.toString('utf8');
    const found = [];
    for (const line of body.split('\n')) {
      try { const j = JSON.parse(line); if (j.message || j.extra) found.push(JSON.stringify({message: j.message, extra: j.extra, tags: j.tags})); } catch (e) {}
    }
    fs.appendFileSync(out, `${new Date().toISOString()} ${req.url} ${body.length}B ${found.join(' | ')}\n`);
