  for (const t of pages) {
    const ws = new WebSocket(t.webSocketDebuggerUrl);
    await new Promise(r => ws.onopen = r);
    const expr = `(() => {
      const stl = 'solid t\\n facet normal 0 0 1\\n  outer loop\\n   vertex 0 0 0\\n   vertex 10 0 0\\n   vertex 0 10 0\\n  endloop\\n endfacet\\nendsolid t\\n';
      const dt = new DataTransfer();
      dt.items.add(new File([stl], ${JSON.stringify(name)}, {type: 'model/stl'}));
      const el = document.elementFromPoint(innerWidth / 2, innerHeight / 2) || document.body;
      el.dispatchEvent(new DragEvent('dragenter', {dataTransfer: dt, bubbles: true, cancelable: true}));
      el.dispatchEvent(new DragEvent('dragover', {dataTransfer: dt, bubbles: true, cancelable: true}));
      el.dispatchEvent(new DragEvent('drop', {dataTransfer: dt, bubbles: true, cancelable: true}));
      return el.tagName + '.' + el.className + ' file=' + dt.files[0].name;
    })()`;
