94	// Waits for the uploads under way, at most `timeout` milliseconds; 0 when
95	// none is left.
96	int wait_for_uploads(uint64_t timeout, void* state)
97	{
98	    Uploads&                     uploads = *static_cast<Uploads*>(state);
99	    std::unique_lock<std::mutex> lock(uploads.mutex);
100	    return uploads.idle.wait_for(lock, std::chrono::milliseconds(timeout), [&uploads] { return uploads.pending == 0; }) ? 0 : 1;
101	}
