103	// This run's log file (GUI_App's set_log_path_and_level names it after the
104	// process id); none when the system writes no log file.
105	std::optional<std::filesystem::path> log_file(const std::string& data_dir)
106	{
107	    const std::filesystem::path folder = std::filesystem::u8path(data_dir) / "log";
108	    if (!std::filesystem::is_directory(folder))
109	        return std::nullopt;
110	    const std::string ending = "_" + std::to_string(get_current_pid()) + ".log.0";
111	    for (const std::filesystem::directory_entry& entry : std::filesystem::directory_iterator(folder)) {
112	        const std::string name = entry.path().filename().string();
113	        if (name.size() > ending.size() && name.compare(name.size() - ending.size(), ending.size(), ending) == 0)
